import time
import spidev
import board
import adafruit_mcp3208
from gpiozero import AnalogIn

def mcp3208_gpiozero(channel):
    if not 0 <= channel <= 7:
        return -1
    try:
        adc = AnalogIn(board.A0 + channel)
        return float(adc.value) / 1023.0
    except Exception:
        return -1

def mcp3208_spidev(channel):
    if not 0 <= channel <= 7:
        return -1
    spi = spidev.SpiDev()
    spi.open(0, 0)
    spi.max_speed_hz = 1000000
    spi.mode = 0
    spi.bits_per_word = 16
    spi.lsbfirst = False
    cmd = [0x01, (channel >> 4) & 0x01, channel & 0x0F]
    try:
        data = spi.xfer2(cmd)
        if len(data) != 3 or data[0] != 0x01 or data[1] != (channel >> 4) & 0x01 or data[2] != (channel & 0x0F):
            return -1
        return ((data[1] & 0x0F) << 8) | data[2]
    except Exception:
        spi.close()
        return -1
    finally:
        spi.close()

def mcp3208_adafruit_gpio(channel):
    if not 0 <= channel <= 7:
        return -1
    mcp = adafruit_mcp3208.MCP3208()
    try:
        return mcp.read_adc(channel)
    except Exception:
        return -1

if __name__ == "__main__":
    print("Testing mcp3208_gpiozero on channel 0...")
    result = mcp3208_gpiozero(0)
    if result == -1:
        print("Error occurred.")
    else:
        print(f"Result: {result}")

    print("\nTesting mcp3208_spidev on channel 0...")
    result = mcp3208_spidev(0)
    if result == -1:
        print("Error occurred.")
    else:
        print(f"Result: {result}")

    print("\nTesting mcp3208_adafruit_gpio on channel 0...")
    result = mcp3208_adafruit_gpio(0)
    if result == -1:
        print("Error occurred.")
    else:
        print(f"Result: {result}")

