import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = None
        self.try_open()

    def try_open(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"SPI device error: {e}")
            sys.exit(1)

    def send_spi_command(self, spi, data):
        try:
            response = spi.xfer2(data)
        except (OSError, IOError) as e:
            print(f"SPI transfer error: {e}")
            return None
        return response

    def extract_10bit(self, response):
        if response is None or len(response) < 3:
            return None
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        if self.spi is None:
            return None
        data_to_send = [0x01, 0x80, 0x00]
        response = self.send_spi_command(self.spi, data_to_send)
        if response is None:
            return None
        raw_data = self.extract_10bit(response)
        return raw_data

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def close(self):
        if self.spi:
            self.spi.close()

    def run(self):
        while True:
            raw_data = self.read_raw_data()
            if raw_data is not None:
                weight = self.convert_to_weight(raw_data)
                if weight is not None:
                    print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)

def main():
    reader = LoadCellReader()
    try:
        reader.run()
    except KeyboardInterrupt:
        print("\nShutdown initiated, cleaning up...")
    finally:
        reader.close()
        print("SPI device closed.")

if __name__ == "__main__":
    main()

# Install SIGTERM handler for clean shutdown
def sigterm_handler(signal, frame):
    print("\nReceived SIGTERM, shutting down...")
    main()
    sys.exit(0)

signal.signal(signal.SIGTERM, sigterm_handler)

