import smbus2
import logging
import time

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus2.SMBus(self.busnum)
        try:
            self.bus.write_byte_data(self.address, 0x06, 0x00)  # Configure register
            if self.debug:
                print("ADS1015 present")
        except Exception as e:
            logging.error(f"Error initializing ADS1015: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            config_reg = (channel << 4) | (pga << 2) | (sps >> 4)
            self.bus.write_byte_data(self.address, 0x06, config_reg)
            time.sleep(0.01)  # Wait for conversion to complete
            high_byte = self.bus.read_byte_data(self.address, 0x00)
            low_byte = self.bus.read_byte_data(self.address, 0x01)
            result = (high_byte << 8) | low_byte
            return result
        except Exception as e:
            logging.error(f"Error reading ADS1015: {e}")
            raise

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            config_reg = (channel << 4) | (pga << 2) | (sps >> 4) | 0x01
            self.bus.write_byte_data(self.address, 0x06, config_reg)
        except Exception as e:
            logging.error(f"Error starting continuous conversion: {e}")
            raise

    def get_last_conversion_results(self):
        try:
            high_byte = self.bus.read_byte_data(self.address, 0x00)
            low_byte = self.bus.read_byte_data(self.address, 0x01)
            result = (high_byte << 8) | low_byte
            return result
        except Exception as e:
            logging.error(f"Error getting last conversion result: {e}")
            raise

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            config_reg = (channel << 4) | (pga << 2) | (sps >> 4)
            config_reg |= (threshold_high << 6) | (threshold_low << 10)
            config_reg |= (active_low << 11) | (traditional_mode << 12) | (latching << 13)
            config_reg |= num_readings
            self.bus.write_byte_data(self.address, 0x06, config_reg)
        except Exception as e:
            logging.error(f"Error starting comparator: {e}")
            raise

    def __del__(self):
        try:
            self.bus.close()
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")

