import logging
import threading
import time
import queue
import RPi.GPIO as GPIO
import spidev
from gpiozero import DigitalInputDevice, AnalogInput
from adafruit_circuitpython_mcp3008 import mcp3008

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.last_event_time = 0

        if self.sensor_type == "digital":
            if not self.gpio_pins:
                raise ValueError("GPIO pins must be provided for digital sensors")
            self.sensor = DigitalInputDevice(self.gpio_pins)
        elif self.sensor_type == "analog":
            if not self.channels:
                raise ValueError("Channels must be provided for analog sensors")
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.mcp3008 = mcp3008.MCP3008(self.spi)
        else:
            raise ValueError("Invalid sensor type. Choose 'digital' or 'analog'.")

        if self.sensor_type == "analog":
            try:
                self.mcp3008.read_adc(self.channels[0])
            except Exception as e:
                logging.error(f"SPI initialization failed: {e}")
                raise

        self.running = True

    def run(self):
        self.running = True
        while self.running:
            try:
                if self.sensor_type == "digital":
                    reading = self.sensor.value
                elif self.sensor_type == "analog":
                    reading = self.mcp3008.read_adc(self.channels[0])
                    reading = ((reading & 0b11111000) >> 2) * 2.44  # Convert to voltage

                if reading >= self.threshold:
                    current_time = time.time()
                    if current_time - self.last_event_time > 0.1:
                        self.last_event_time = current_time
                        if self.log_queue:
                            self.log_queue.put((self.sensor_id, reading))
                        else:
                            print(f"Sound event detected by sensor {self.sensor_id}: {reading}")

                time.sleep(1 / self.sample_rate)

            except Exception as e:
                logging.error(f"Error reading sensor {self.sensor_id}: {e}")

    def stop(self):
        self.running = False
        if self.sensor_type == "digital":
            GPIO.cleanup()

def main():
    import argparse

    parser = argparse.ArgumentParser(description="Sound Sensor")
    parser.add_argument("--sensor_type", choices=["digital", "analog"], required=True)
    parser.add_argument("--threshold", type=int, default=500)
    parser.add_argument("--sample_rate", type=int, default=10)
    parser.add_argument("--log_file", type=str, default=None)
    parser.add_argument("--gpio_pins", type=int, nargs="+", default=[])
    parser.add_argument("--channels", type=int, nargs="+", default=[])
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=str, nargs="+", required=True)

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO)

    sensors = []
    for sensor_id in args.sensor_ids:
        if args.sensor_type == "digital":
            sensors.append(SoundSensor(sensor_id, "digital", args.threshold, args.sample_rate, args.gpio_pins, [], args.spi_speed, queue.Queue()))
        elif args.sensor_type == "analog":
            sensors.append(SoundSensor(sensor_id, "analog", args.threshold, args.sample_rate, [], args.channels, args.spi_speed, queue.Queue()))

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()

