from contextlib import contextmanager

logging.basicConfig(stream=sys.stderr, level=logging.INFO)

@contextmanager
def serial_port(port='/dev/rfcomm4', baudrate=38400):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        ser.open()
        try:
            yield ser
        finally:
            ser.close()
    except serial.SerialException as e:
        logging.error(f"Error opening serial port: {e}")
        raise

def main():
    try:
        with serial_port() as ser:
            if ser.is_open:
                ser.baudrate = 38400
                ser.bytesize = 8
                ser.parity = serial.PARITY_NONE
                ser.stopbits = serial.STOPBITS_ONE

            while True:
                user_input = input("Enter data (or 'q' to quit): ").encode('utf-8')
                if user_input.strip() == 'q':
                    break

                try:
                    ser.write(bytes('X' + user_input))
                    logging.info(f"Transmitted {len(user_input)} bytes")
                except serial.SerialException as e:
                    logging.error(f"Error during transmission: {e}")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()

