class ServoShutter:
    def __init__(self, pin):
        self.servo = AngularServo(pin)
        self.servo.angle = 90  # Initialize to center position

    def move_to_open(self):
        self.servo.angle = 180
        print("Camera shutter opened.")

    def move_to_closed(self):
        self.servo.angle = 0
        print("Camera shutter closed.")

    def run(self):
        try:
            self.move_to_open()
            time.sleep(0.5)
            self.move_to_closed()
            time.sleep(0.5)

            while True:
                pass  # Keep running until interrupted

        except KeyboardInterrupt:
            print("\nServo shutter operation stopped by user.")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            try:
                self.servo.close()
            except Exception as e:
                print(f"Error releasing servo pin: {e}")

if __name__ == "__main__":
    servo_shutter = ServoShutter(18)
    signal.signal(signal.SIGINT, servo_shutter.servo.after_callback)
    servo_shutter.run()

