def read_sensors():
    try:
        # Configure all pins as inputs with pull-ups enabled
        bus.write_byte_data(PCF8574_ADDR, 0x00, 0xFF)
        # Read the input port register
        sensor_state = bus.read_byte_data(PCF8574_ADDR, 0x01)

        # Check each sensor pin (P0 to P7)
        for i in range(8):
            if not (sensor_state >> i) & 0x01:
                print(f"Obstacle detected by sensor {i}")

    except Exception as e:
        print(f"Error reading sensors: {e}")
        time.sleep(1)

if __name__ == "__main__":
    try:
        while True:
            read_sensors()
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting sensor reader...")
    finally:
        bus.close()
        print("I2C bus closed.")

import time
import subprocess
import gpiozero
import datetime
from gpiozero.pins.pigpio import PiGPIOUnavailable

def simulate_light(pin):
    hour = int(datetime.datetime.now().strftime("%H"))
    if 6 <= hour < 18:  # Daytime
        return round(600 + (1000 - 600) * (hour - 6) / 12)
    else:  # Night
        return round(100 + (300 - 100) * (24 - hour) / 12)

def simulate_temperature():
    return round(20 + (30 - 20) * (datetime.datetime.now().minute / 60))

def simulate_voltage_current(light_level):
    if light_level > 300:
        return 11.5, round(1.5 + (2.5 - 1.5) * (light_level - 300) / 700)
    else:
        return 10.0, round(0.5 + (1.0 - 0.5) * (300 - light_level) / 700)

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=1)
        output = result.stdout.strip()
        if output.endswith('C'):
            return float(output[:-1])
        else:
            print("Warning: Failed to read Pi temperature.")
            return None
    except (subprocess.TimeoutExpired, FileNotFoundError):
        print("Warning: vcgencmd command not found or failed.")
        return None

def log_cycle(light_lux, temp_C, voltage, current, pi_temp):
    print(f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}: Light={light_lux} lux, Temp={temp_C}°C, Voltage={voltage}V, Current={current}A, Pi Temp={pi_temp}°C")

