    light_pin = gpiozero.InputDevice(17, pull_up=False)
    temp_pin = gpiozero.InputDevice(4, pull_up=False)

    try:
        light_pin.on_read = simulate_light(light_pin)
        temp_pin.on_read = simulate_temperature

        while True:
            light_lux = light_pin.read()
            temp_C = simulate_temperature()
            voltage, current = simulate_voltage_current(light_lux)
            pi_temp = read_pi_temperature()

            log_cycle(light_lux, temp_C, voltage, current, pi_temp if pi_temp is not None else "N/A")

            if light_lux < 300:
                print("WARNING: Possible solar panel performance issues due to low light.")
            if temp_C > 35:
                print("WARNING: Simulated cooling system activated due to high temperature.")
            if pi_temp is not None and pi_temp > 75:
                print("CRITICAL: Simulated system shutdown due to overheating.")

            time.sleep(5)

    except PiGPIOUnavailable:
        print("Error: GPIO library not available. Exiting gracefully.")
    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting gracefully.")
    finally:
        light_pin.close()
        temp_pin.close()

if __name__ == '__main__':
    main()

