import smbus2
import time
import logging
import sys
import signal

logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    def __init__(self):
        self.bus = None
        self.crc_error = False

        try:
            self.bus = smbus2.SMBus(1)
            self.bus.write_byte(0x38, 0x71)
            time.sleep(0.01)
            if self.bus.read_byte(0x38) & 0x80:
                raise Exception("DHT20 sensor not detected")
        except Exception as e:
            logging.error(f"I2C error: {e}")
            self.bus = None

    def measure(self):
        if not self.bus:
            return None, None, True

        try:
            self.bus.write_byte(0x38, 0x33)
            self.bus.write_byte(0x38, 0x00)

            start_time = time.time()
            while time.time() - start_time < 0.1:
                if not (self.bus.read_byte(0x38) & 0x80):
                    break
                time.sleep(0.01)

            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            crc = self.calculate_crc8(data[:6])
            if crc != data[6]:
                self.crc_error = True
                return None, None, self.crc_error

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]

            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return temperature, humidity, self.crc_error

        except Exception as e:
            logging.error(f"Measurement error: {e}")
            return None, None, True

    def calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            for _ in range(8):
                if crc & 0x01:
                    crc ^= 0x31
                else:
                    crc <<= 1
                crc >>= 1
                if byte & 0x80:
                    byte <<= 1
                    byte ^= 0x10
            byte >>= 1
        return crc

def signal_handler(signal, frame):
    print("\nExiting gracefully...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    dht20 = DHT20()
    temp, hum, crc_error = dht20.measure()

    if not crc_error:
        print(f"Temperature: {temp:.2f} °C, Humidity: {hum:.2f} %")
    else:
        print("Error: CRC mismatch or other measurement failure.")

    dht20.bus.close()

