            return None, None, True

    def calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            for _ in range(8):
                if crc & 0x01:
                    crc ^= 0x31
                else:
                    crc <<= 1
                crc >>= 1
                if byte & 0x80:
                    byte <<= 1
                    byte ^= 0x10
            byte >>= 1
        return crc

def signal_handler(signal, frame):
    print("\nExiting gracefully...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    dht20 = DHT20()
    temp, hum, crc_error = dht20.measure()

    if not crc_error:
        print(f"Temperature: {temp:.2f} °C, Humidity: {hum:.2f} %")
    else:
        print("Error: CRC mismatch or other measurement failure.")

    dht20.bus.close()
