def move_servo(servo, angle):
    try:
        duty_cycle = round((angle - 0) / 90 * 12.5, 2)
        servo.ChangeDutyCycle(duty_cycle)
    except Exception as e:
        logging.error(f"Error moving servo1: {e}")
        if servo is servo1:
            global servo_active
            servo_active = False
            logging.info("Switched to servo2 due to repeated failures.")

servo_active = True
failure_count = 0

while True:
    temp = random.uniform(15, 35)
    logging.info(f"Simulated temperature: {temp:.1f}°C")

    if servo_active:
        if temp < 20:
            target_angle = 0
        elif 20 <= temp < 25:
            target_angle = 45
        elif 25 <= temp < 30:
            target_angle = 90
        elif 30 <= temp < 35:
            target_angle = 135
        else:
            target_angle = 180

        current_angle = servo1.get_duty_cycle() * 90 / 12.5
        if abs(target_angle - current_angle) > 5:
            for i in range(abs(target_angle - current_angle) // 5):
                move_servo(servo1, current_angle + (target_angle - current_angle) // 5 * (target_angle > current_angle))
                time.sleep(0.1)
            current_angle = target_angle
        else:
            move_servo(servo1, target_angle)
    else:
        if temp < 20:
            target_angle = 0
        elif 20 <= temp < 25:
            target_angle = 45
        elif 25 <= temp < 30:
            target_angle = 90
        elif 30 <= temp < 35:
            target_angle = 135
        else:
            target_angle = 180

        current_angle = servo2.get_duty_cycle() * 90 / 12.5
        if abs(target_angle - current_angle) > 5:
            for i in range(abs(target_angle - current_angle) // 5):
                move_servo(servo2, current_angle + (target_angle - current_angle) // 5 * (target_angle > current_angle))
                time.sleep(0.1)
            current_angle = target_angle
        else:
            move_servo(servo2, target_angle)

    if servo_active and temp < 20 and random.random() < 0.1:  # 10% failure rate
        failure_count += 1
        if failure_count >= 3:
            servo_active = False
            failure_count = 0

    time.sleep(5)

# Cleanup on exit
try:
    servo1.stop()
    servo2.stop()
    GPIO.cleanup()
except Exception as e:
    logging.error(f"Cleanup failed: {e}")

