import sys
import time
from datetime import datetime

def celsius_to_fahrenheit(celsius):
    return celsius * 9/5 + 32

def log_temperature(ser, csv_file):
    if not csv_file.writable():
        print("Error: CSV file is not writable.", file=sys.stderr)
        return

    writer = csv.writer(csv_file)
    header_written = False

    try:
        while True:
            try:
                line = ser.readline().decode('ascii').strip()
                if not line:
                    continue

                try:
                    celsius = float(line)
                    fahrenheit = celsius_to_fahrenheit(celsius)
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    writer.writerow([timestamp, celsius, fahrenheit])
                except ValueError:
                    print("Warning: Skipping malformed line -", line, file=sys.stderr)

            except serial.SerialException as e:
                print("Error: Unable to read from serial port.", file=sys.stderr)
                break

    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        csv_file.close()

def main():
    serial_port = "/dev/ttyACM0"
    baud_rate = 115200
    timeout = 1

    try:
        ser = serial.Serial(serial_port, baud_rate, timeout=timeout, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE)
        csv_file_path = "temperature_log.csv"
        csv_file = open(csv_file_path, "a", newline='')

        if csv_file.tell() == 0:
            writer = csv.writer(csv_file)
            writer.writerow(["timestamp", "celsius", "fahrenheit"])

        log_temperature(ser, csv_file)

    except serial.SerialException as e:
        print(f"Error: Unable to open serial port {serial_port}. {e}", file=sys.stderr)
        return 1

    finally:
        ser.close()
        csv_file.close()

if __name__ == "__main__":
    main()

