                        logging.warning("CRC mismatch, retrying...")
                        break
                    continue

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                humidity = humidity_raw / (1 << 20) * 100
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                temperature = temperature_raw / (1 << 19) * 200 - 50

                self.cached_temp = temperature
                self.cached_humidity = humidity
                self.last_update_time = current_time
                return temperature, humidity

            except OSError as e:
                logging.warning(f"I2C error during read: {e}")
                self.max_attempts -= 1
                if self.max_attempts == 0:
                    return None, None
                time.sleep(self.retry_interval)

        logging.error("All measurement attempts failed")
        return None, None

    def calculate_crc8(self, data: bytes) -> int:
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc

# Example usage:
if __name__ == "__main__":
    try:
        with DHT20() as dht20:
            if not dht20.begin():
                print("Failed to initialize DHT20 sensor. Exiting...")
                exit(0)

            while True:
                temp, humidity = dht20.get_temperature_and_humidity()
                if temp is not None and humidity is not None:
                    print(f"Temperature: {temp:.2f} °C, Humidity: {humidity:.2f}%")
                else:
                    print("Failed to read from DHT20 sensor.")
                time.sleep(2)
    except KeyboardInterrupt:
        print("\nExiting...")
    except SystemExit as e:
        print(f"Exiting with code {e}")
