import os

# Configure logging
logging.basicConfig(filename='wildlife_monitoring.log', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def read_dht22(pin):
    attempts = 0
    while attempts < 3:
        try:
            dht_device = adafruit_dht.DHT22(board.D4 if pin == 4 else board.D17)
            temperature, humidity = dht_device.read()
            return temperature, humidity
        except Exception as e:
            attempts += 1
            logging.error(f"Attempt {attempts} failed for pin {pin}: {e}")
            time.sleep(2)
    return None, None

def check_anomaly(temp, hum):
    if temp is not None and (temp > 35 or temp < 5):
        log_anomaly("Temperature")
    if hum is not None and hum > 90:
        log_anomaly("Humidity")

def log_anomaly(anomaly_type):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    logging.error(f"{anomaly_type.capitalize()} anomaly detected at {timestamp} on pin {pin}")
    print(f"{anomaly_type.capitalize()} anomaly detected at {timestamp} on pin {pin}")

def main():
    global pin
    pin = 4  # Initialize with GPIO4, change to 17 for the second sensor

    while True:
        try:
            temp1, hum1 = read_dht22(pin)
            if temp1 is not None:
                pin = 4  # Reset pin for the next iteration
                check_anomaly(temp1, hum1)

            # Repeat for the second sensor connected to GPIO17
            temp2, hum2 = read_dht22(17)
            if temp2 is not None:
                pin = 17
                check_anomaly(temp2, hum2)

        except KeyboardInterrupt:
            logging.info("Program terminated by user.")
            break
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            break

        time.sleep(60)

if __name__ == "__main__":
    main()

