    else:
        with open(cloud_log, 'a') as cloud_log_file:
            cloud_log_file.write(f'Simulated cloud push failure for sensor {random.choice([17, 27])}\n')

def read_sensor(device, pin, retries=3):
    for attempt in range(retries):
        try:
            return device(pin)
        except Exception as e:
            logging.error(f"Sensor read failure on pin {pin}: {e}")
            if attempt < retries - 1:
                time.sleep(2)
            else:
                logging.error(f"Failed to read sensor after {retries} attempts.")
                return None

try:
