                    last_high_humidity_alert[pin] = datetime.now()
                    simulate_cloud_push()
            elif hum < 45:
                low_humidity_counter[pin] += 1
                if low_humidity_counter[pin] >= 3 and (datetime.now() - timedelta(minutes=30)) > last_low_humidity_alert[pin]:
                    log_alert(pin, 'Low Humidity Alert')
