import time
import subprocess
import signal
from gpiozero import PWMOutputDevice
import psutil

class FanController:
    def __init__(self, fan_pin):
        self.fan = PWMOutputDevice(fan_pin)
        self.fan.frequency = 100
        self.last_temp = None
        self.duty_cycle = 100

    def update_duty_cycle(self):
        try:
            temp_celsius = float(subprocess.check_output("vcgencmd measure_temp", shell=True).decode().strip())
        except (subprocess.CalledProcessError, ValueError):
            print("Error reading CPU temperature. Using last known duty cycle.", file=sys.stderr)
            return

        if self.last_temp is None:
            self.last_temp = temp_celsius
            self.duty_cycle = 100
            return

        if temp_celsius > 70:
            self.duty_cycle = 100
        elif temp_celsius > 60:
            self.duty_cycle = 85
        elif temp_celsius > 50:
            self.duty_cycle = 70
        elif temp_celsius > 40:
            self.duty_cycle = 50
        elif temp_celsius > 32:
            self.duty_cycle = 25
        elif temp_celsius > 25:
            self.duty_cycle = 15
        else:
            self.duty_cycle = 0

        self.last_temp = temp_celsius
        self.fan.value = self.duty_cycle

    def run(self):
        while True:
            self.update_duty_cycle()
            time.sleep(5)

def signal_handler(signal, frame):
    print("\nExiting...")
    fan_controller.fan.close()
    sys.exit(0)

if __name__ == "__main__":
    fan_pin = 14
    fan_controller = FanController(fan_pin)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    fan_controller.run()

