import time
import logging
import subprocess
import board
from gpiozero import PWMFan
from adafruit_circuitpython_motor import servo
import os

class FanController:
    def __init__(self):
        self.fan = PWMFan(board.D4)
        self.fan.frequency = 100
        self.cpu_temp_file = "/sys/class/thermal/thermal_zone0/temp"
        self.cpu_temp_thresholds = {
            70: 100,
            60: 85,
            50: 70,
            40: 50,
            32: 25,
            25: 15,
            25: 0,
        }
        self.last_log_time = time.time()

    def read_cpu_temp(self):
        try:
            with open(self.cpu_temp_file, 'r') as temp_file:
                temp_celsius = round((float(temp_file.read().strip()) / 1000) * 100, 2)
                return temp_celsius
        except Exception as e:
            logging.error(f"Error reading CPU temperature: {e}")
            return None

    def set_fan_speed(self, temp):
        if temp is not None:
            for threshold, duty_cycle in self.cpu_temp_thresholds.items():
                if temp >= threshold:
                    self.fan.value = duty_cycle
                    logging.info(f"Temperature: {temp}°C, Fan Speed: {duty_cycle}%")
                    break

    def run(self):
        try:
            while True:
                current_time = time.time()
                if current_time - self.last_log_time >= 5:
                    temp = self.read_cpu_temp()
                    self.set_fan_speed(temp)
                    self.last_log_time = current_time
                time.sleep(0.1)
        except (KeyboardInterrupt, SIGTERM, SIGINT):
            self.fan.close()
            logging.info("Fan controller shutting down.")

    def cleanup(self):
        self.fan.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    fan_controller = FanController()
    try:
        fan_controller.run()
    except Exception as e:
        fan_controller.cleanup()
        raise e
    finally:
        fan_controller.cleanup()

