            with open(self.cpu_temp_file, 'r') as temp_file:
                temp_celsius = round((float(temp_file.read().strip()) / 1000) * 100, 2)
                return temp_celsius
        except Exception as e:
            logging.error(f"Error reading CPU temperature: {e}")
            return None

    def set_fan_speed(self, temp):
        if temp is not None:
            for threshold, duty_cycle in self.cpu_temp_thresholds.items():
                if temp >= threshold:
                    self.fan.value = duty_cycle
                    logging.info(f"Temperature: {temp}°C, Fan Speed: {duty_cycle}%")
                    break

    def run(self):
        try:
            while True:
                current_time = time.time()
                if current_time - self.last_log_time >= 5:
                    temp = self.read_cpu_temp()
                    self.set_fan_speed(temp)
                    self.last_log_time = current_time
                time.sleep(0.1)
        except (KeyboardInterrupt, SIGTERM, SIGINT):
            self.fan.close()
            logging.info("Fan controller shutting down.")

    def cleanup(self):
        self.fan.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    fan_controller = FanController()
    try:
        fan_controller.run()
    except Exception as e:
        fan_controller.cleanup()
        raise e
    finally:
        fan_controller.cleanup()
```

This code defines a `FanController` class that initializes a PWM fan on GPIO14, reads the CPU temperature every 5 seconds, and sets the fan duty cycle based on predefined temperature thresholds. It handles temperature-read failures gracefully and releases GPIO resources cleanly on program termination, handling KeyboardInterrupt, SIGTERM, and SIGINT signals.

