SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 5  # seconds

ser = None

def init_serial():
    global ser
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        if not ser.is_open:
            ser.open()
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        exit(1)

def read_sensor_data():
    global ser
    if ser is None or not ser.is_open:
        return None

    try:
        line = ser.readline().decode('utf-8').strip()
        if not line:
            print("No data received from sensor. Check connection.")
            return None

        match = re.match(r'(\d+\.\d+),(\d+\.\d+)', line)
        if not match:
            print("Malformed line received from sensor.")
            return None

        temp, humidity = map(float, match.groups())
        print(f"Temperature: {temp}°C, Humidity: {humidity}%")

        if temp > 30.0:
            print("ALERT: Temperature exceeds 30.0°C")
        if humidity > 70.0:
            print("ALERT: Humidity exceeds 70.0%")

    except serial.SerialTimeoutException:
        print("Sensor timeout. Check sensor and connection.")
    except Exception as e:
        print(f"Unexpected error: {e}")

def main():
    init_serial()
    try:
        while True:
            read_sensor_data()
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        if ser is not None and ser.is_open:
            ser.close()

