import time
import board
import adafruit_ina219.ina219 as ina219
import busio
import smbus2
import logging

# Setup logging
logging.basicConfig(level=logging.INFO)

class UPSPlus:
    def __init__(self, i2c_bus, device_address):
        self.i2c_bus = busio.I2C(i2c_bus)
        self.device = smbus2.SMBus(self.i2c_bus)
        self.device_address = device_address

    def read_register(self, reg_addr):
        try:
            return self.device.read_byte_data(self.device_address, reg_addr)
        except Exception as e:
            logging.error(f"Error reading register {reg_addr}: {e}")
            return None

    def read_multi_byte(self, start_reg, num_bytes):
        data = []
        for i in range(start_reg, start_reg + num_bytes):
            reg_value = self.read_register(i)
            if reg_value is not None:
                data.append(reg_value)
            else:
                break
        return bytes(data)

class UPSMonitor:
    def __init__(self, ups):
        self.ups = ups
        self.ina219_power = ina219.INA219(i2c=self.ups.i2c_bus, address=0x40, shunt_resistance=0.00725)
        self.ina219_battery = ina219.INA219(i2c=self.ups.i2c_bus, address=0x45, shunt_resistance=0.005)

    def read_sensor_data(self):
        try:
            power_data = self.ina219_power.bus_voltage(), self.ina219_power.shunt_voltage(), self.ina219_power.bus_power()
            battery_data = self.ina219_battery.bus_voltage(), self.ina219_battery.shunt_voltage(), self.ina219_battery.bus_power()
            return {
                "power": {
                    "voltage": power_data[0],
                    "current_mA": power_data[2] / 1000,
                    "power_mW": power_data[2]
                },
                "battery": {
                    "voltage": battery_data[0],
                    "current_mA": battery_data[2] / 1000,
                    "power_mW": battery_data[2]
                }
            }
        except Exception as e:
            logging.error(f"Error reading sensor data: {e}")
            return None

    def read_ups_data(self):
        ups_data = self.ups.read_multi_byte(0x00, 0x1B)
        if ups_data:
            return {
                "processor_voltage": (ups_data[1] << 8) | ups_data[0],
                "rpi_voltage": (ups_data[3] << 8) | ups_data[2],
                "battery_voltage": (ups_data[5] << 8) | ups_data[4],
                "typec_voltage": (ups_data[7] << 8) | ups_data[6],
                "microusb_voltage": (ups_data[9] << 8) | ups_data[8],
                "battery_temp": (ups_data[11] << 8) | ups_data[10],
                "full_battery_voltage": (ups_data[13] << 8) | ups_data[12],
                "empty_battery_voltage": (ups_data[15] << 8) | ups_data[14],
                "battery_protection_voltage": (ups_data[17] << 8) | ups_data[16],
                "capacity_percent": (ups_data[19] << 8) | ups_data[18],
                "sampling_period": (ups_data[21] << 8) | ups_data[20],
                "power_state": ups_data[23],
                "shutdown_countdown": ups_data[24],
                "auto_power_on": (ups_data[25] >> 7) & 0x01,
                "restart_countdown": ups_data[26]
            }
        else:
            logging.error("Error reading UPS data.")
            return None

def main():
    try:
        i2c_bus = busio.I2C(board.I2C())
        ups = UPSPlus(i2c_bus, 0x17)

        ups_monitor = UPSMonitor(ups)

        while True:
            sensor_data = ups_monitor.read_sensor_data()
            ups_data = ups_monitor.read_ups_data()

            if sensor_data:
                print("Sensor Data:")
                print(f"Power: Voltage={sensor_data['power']['voltage']:.2f} V, Current={sensor_data['power']['current_mA']:.2f} mA, Power={sensor_data['power']['power_mW']:.2f} mW")
                print(f"Battery: Voltage={sensor_data['battery']['voltage']:.2f} V, Current={sensor_data['battery']['current_mA']:.2f} mA, Power={sensor_data['battery']['power_mW']:.2f} mW")

            if ups_data:
                print("\nUPS Data:")
                for key, value in ups_data.items():
                    print(f"{key}: {value}")

            time.sleep(2)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        i2c_bus.close()

if __name__ == "__main__":
    main()

