import os
import time
import subprocess
from gpiozero import PWMOutputDevice
import signal
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)

# Define fan PWM pin
FAN_PIN = 14

# Define fan speed thresholds and corresponding duty cycles
TEMP_THRESHOLDS = {
    70: 100,
    60: 85,
    50: 70,
    40: 50,
    32: 25,
    25: 15,
}

class FanController:
    def __init__(self):
        self.fan = None
        self.last_temp = 0
        self.last_duty_cycle = 0

    def setup(self):
        try:
            self.fan = PWMOutputDevice(FAN_PIN)
            self.fan.frequency = 100
            self.fan.start()
        except IOError:
            logging.warning("Hardware PWM not available. Running in degraded mode.")
            self.fan = None

    def get_cpu_temp(self):
        try:
            result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True)
            if result.returncode != 0:
                logging.error(f"Failed to get CPU temperature: {result.stderr}")
                return self.last_temp
        except Exception as e:
            logging.error(f"Error getting CPU temperature: {e}")
        return float(result.stdout.strip())

    def update_fan_speed(self):
        temp = self.get_cpu_temp()
        if temp > self.last_temp:
            self.last_temp = temp
            for threshold, duty_cycle in TEMP_THRESHOLDS.items():
                if temp > threshold:
                    self.fan.value = duty_cycle if self.fan else duty_cycle
                    break
        else:
            self.fan.value = 0 if self.fan else 0

    def run(self):
        self.setup()
        while True:
            self.update_fan_speed()
            logging.info(f"CPU temp: {self.last_temp}°C, Fan speed: {self.fan.value}%")
            time.sleep(5)

def signal_handler(signal, frame):
    logging.info("Exiting...")
    if hasattr(FanController, "instance"):
        FanController.instance.fan.stop() if FanController.instance.fan else None
        sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

FanController.instance = FanController()
FanController.instance.run()

