import sys
import time
import re

try:
    import RPi.GPIO as GPIO
    import gpiozero
except ImportError:
    GPIO = None

vader_lexicon = {
    "amazing": 0.8, "fantastic": 0.7, "great": 0.6, "wonderful": 0.5,
    "good": 0.4, "excellent": 0.3, "terrible": -0.3, "bad": -0.4,
    "horrible": -0.5, "awful": -0.6, "terrific": -0.7, "poor": -0.8,
    "disappointing": -0.9, "horrendous": -1.0, "miserable": -1.0,
    "dreadful": -1.0, "awful": -1.0, "horrific": -1.0, "pathetic": -1.0
}

def get_sentiment_score(word):
    return vader_lexicon.get(word.lower(), 0.0)

def analyze_sentiment(sentence):
    words = re.findall(r'\b\w+\b', sentence.lower())
    scores = [get_sentiment_score(word) for word in words if word]
    avg_score = sum(scores) / len(scores) if scores else 0.0

    if avg_score > 0.2:
        return 'Positive'
    elif avg_score < -0.2:
        return 'Negative'
    else:
        return 'Neutral'

def main():
    global GPIO
    if GPIO is not None:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(17, GPIO.OUT)  # Green LED
        GPIO.setup(18, GPIO.OUT)  # Red LED
        GPIO.output(17, GPIO.LOW)
        GPIO.output(18, GPIO.LOW)
    else:
        print("GPIO functionality is not available.")

    sentence = input("Enter a sentence: ")
    sentiment = analyze_sentiment(sentence)
    print(f"Sentiment: {sentiment}")

    if GPIO is not None:
        if sentiment == 'Positive':
