import pigpio
import signal
import threading

class OutputPin:
    def __init__(self, pin, value_list):
        if not pigpio.pi():
            raise RuntimeError("Failed to connect to pigpio daemon")
        if pin < 0 or pin > pigpio.GPIO_NUM_MAX:
            raise ValueError(f"Invalid pin number: {pin}")
        if not all(isinstance(v, int) for v in value_list) or len(value_list) < 2:
            raise ValueError("value_list must be a tuple of at least two integers")
        self.pi = pigpio.pi()
        self.pin = pin
        self.value_list = value_list
        self.current_value = value_list[0]
        self.shutdown_lock = threading.Lock()
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.write(self.pin, self.current_value)

    def shutdown(self):
        with self.shutdown_lock:
            self.pi.set_mode(self.pin, pigpio.INPUT)

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError(f"Value must be in {self.value_list}")
        self.current_value = value
        self.pi.write(self.pin, self.current_value)

class TriggerPin(OutputPin):
    def __init__(self, pin, value_list, pulse_duration_us=100, pulse_high=True):
        super().__init__(pin, value_list)
        self.pulse_duration_us = pulse_duration_us
        self.pulse_high = pulse_high
        self.pulse_lock = threading.Lock()

    def trigger(self):
        with self.pulse_lock:
            if self.pulse_high:
                self.pi.pulse(self.pin, self.pulse_duration_us, self.current_value)
            else:
                self.pi.pulse(self.pin, self.pulse_duration_us, 0)

def signal_handler(signal, frame):
    print("Cleaning up and exiting...")
    ExampleOutput.shutdown()
    ExampleTrigger.shutdown()
    pigpio.stop()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)

ExampleOutput = OutputPin(21, (0, 1))
ExampleTrigger = TriggerPin(20, (0, 1), pulse_duration_us=100, pulse_high=True)

try:
    ExampleOutput.set_value(1)
    ExampleTrigger.trigger()
except Exception as e:
    print(f"An error occurred: {e}")

import logging
import time
import signal
import sys
import threading
import zmq
from gpiozero import PWMOutputDevice, OutputDevice, NotInitialized
from adafruit_circuitpython_pwmio import pwmio
import board

class PIDHandler:
    def __init__(self, pwm: bool = True):
        self.logger = logging.getLogger(__name__)
        self.pwm = pwm
        self.last_msg = time.time()
        self.global_err_state = False
        self.gpio_device = None
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.REP)
        self.socket.bind("tcp://*:" + str(12345))

        try:
            if self.pwm:
                self.gpio_device = pwmio.PIO(1, board_id=1)
                self.error_output = self.gpio_device.pwm[12]
                self.error_output.frequency = 1000
                self.error_output.duty_cycle = 0.0
            else:
                self.gpio_device = OutputDevice(10)
                self.error_output = self.gpio_device
        except NotInitialized:
            self.logger.error("GPIO library not initialized. Ensure this script is run on a Raspberry Pi.")
            sys.exit(1)

    def update_error_output(self):
        if self.pwm:
            self.error_output.duty_cycle = 1.0 if self.global_err_state else 0.0
        else:
            self.error_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def cleanup(self):
        if self.gpio_device:
            self.gpio_device.close()

    def handle_message(self):
        try:
            msg = self.socket.recv(zmq.NOBLOCK)
            if msg is None:
                if time.time() - self.last_msg > 20:
                    self.logger.warning("No data received for 20 seconds. Triggering error output.")
                    self.set_error_output(True)
                return

            self.last_msg = time.time()
            # Process subscription callbacks here
            self.logger.info(f"Received message: {msg}")

        except zmq.error.Again:
            if time.time() - self.last_msg > 20:
                self.logger.warning("No data received for 20 seconds. Triggering error output.")
                self.set_error_output(True)

    def signal_handler(self, signum, frame):
        self.logger.info(f"Received signal {signum}. Cleaning up resources.")
        self.cleanup()
        sys.exit(0)

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        while True:
            self.handle_message()
            time.sleep(0.1)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    pid_handler = PIDHandler(pwm=True)
    pid_handler.run()

