import time
import sys

class OutputPinException(Exception):
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("Pin number must be between 0 and 31")
        if initial_value not in [0, 1]:
            raise ValueError("Initial value must be 0 or 1")

        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise OutputPinException("pigpio daemon not reachable")

        try:
            self.pi.set_mode(pin_number, pigpio.OUTPUT)
        except Exception as e:
            self.pi.stop()
            raise OutputPinException("Failed to set pin mode") from e

        self.pin_number = pin_number
        self.value = initial_value
        self.pi.write(pin_number, self.value)

    def set_value(self, value: int):
        if value not in [0, 1]:
            raise ValueError("Value must be 0 or 1")

        try:
            self.pi.write(self.pin_number, value)
            self.value = value
        except Exception as e:
            self.pi.stop()
            raise OutputPinException("Failed to write to pin") from e

    def shutdown(self):
        try:
            self.pi.write(self.pin_number, pigpio.INPUT)
        except Exception as e:
            pass  # Ignore errors in shutdown

        self.pi.stop()

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 1)
        for _ in range(5):
            pin.set_value(not pin.value)
            time.sleep(0.5)
        pin.shutdown()
    except OutputPinException as e:
        print(f"Error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)

