from gpiozero import Button, LED
from signal import sigint_signal, SIGINT

class HomeSecuritySystem:
    def __init__(self):
        try:
            self.reed_switch = Button(19, pull_up=False, bounce_time=0.05)
            self.siren_led = LED(26)
        except ValueError as e:
            print(f"Error: {e}. Ensure reed switch is connected to GPIO19 and LED to GPIO26.")
            sys.exit(1)

        self.armed = True
        self.sample_count = 0
        sigint_signal(self.cleanup)

    def monitor(self):
        while self.armed:
            self.sample_count += 1
            if self.reed_switch.is_pressed:
                print(f"Sample {self.sample_count}: Door opened while armed! Lighting siren.")
                self.siren_led.on()
            else:
