class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.prev_clk = None
        self.direction = None
        self.button_thread = None

        PololuDriver(self.clk_pin, self.dt_pin)
        self.clk_button = GPIOIn(self.clk_pin, pull_up=True, bounce_time=0.005)
        self.dt_button = Button(self.dt_pin, pull_up=True, bounce_time=0.005)

        if callable(self.callback):
            self.callback_wrapper = self.callback_with_try_except
        else:
            raise ValueError("The provided callback is not callable.")

    def callback_with_try_except(self, value):
        try:
            self.callback(value)
        except Exception as e:
            print(f"Callback execution failed: {e}")

    def update_counter(self, clk, dt):
        if clk != self.prev_clk:
            self.prev_clk = clk
            if dt == self.prev_clk:
                self.direction = "CW"
            else:
                self.direction = "CCW"

            if self.direction == "CW":
                self.counter += 1
            else:
                self.counter -= 1

            self.callback_wrapper(self.counter)

    def run(self):
        while True:
            clk = self.clk_button.value
            dt = self.dt_button.value
            self.update_counter(clk, dt)
            time.sleep(0.001)  # Adjust the sleep time as needed

    def start(self):
        self.button_thread = threading.Thread(target=self.run)
        self.button_thread.start()

