import logging
import time
import random
import RPi.GPIO as GPIO
from gpiozero import MotionSensor
import threading

# Configure logging
logging.basicConfig(filename='art_installation.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Define actuators
ACTUATORS = [activate_light, activate_sound, activate_motor]

def activate_light():
    print("Light activated")
    logging.info("Activated light")

def activate_sound():
    print("Sound activated")
    logging.info("Activated sound")

def activate_motor():
    print("Motor activated")
    logging.info("Activated motor")

def read_sensor(pin):
    try:
        return GPIO.input(pin) == GPIO.HIGH
    except Exception as e:
        logging.error(f"Error reading sensor on pin {pin}: {e}")
        return False

def main_loop():
    GPIO.setmode(GPIO.BCM)
    pir_1 = MotionSensor(17, pull_up=True)
    pir_2 = MotionSensor(18, pull_up=True)

    last_triggered = [False, False]
    trigger_times = [0, 0]

    try:
        while True:
            if not pir_1.motion_detected:
                if not last_triggered[0]:
                    trigger_times[0] = time.time()
                    last_triggered[0] = True
                    logging.info("Intrusion Detected - PIR 1")
                    trigger_random_actuator()
                    time.sleep(0.1)  # Debounce delay

            if not pir_2.motion_detected:
                if not last_triggered[1]:
                    trigger_times[1] = time.time()
                    last_triggered[1] = True
                    logging.info("Intrusion Detected - PIR 2")
                    trigger_random_actuator()
                    time.sleep(0.1)  # Debounce delay

            if (time.time() - max(trigger_times)) < 0.5:
                if all(last_triggered):
                    logging.warning("Confirmed Intrusion")
                    for actuator in ACTUATORS:
                        actuator()
                    last_triggered = [False, False]
                    trigger_times = [0, 0]

            time.sleep(0.05)

    except KeyboardInterrupt:
        logging.info("Exiting gracefully")
    except RuntimeError as e:
        logging.error(f"GPIO initialization error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()

def trigger_random_actuator():
    random_actuator_index = random.randint(0, len(ACTUATORS) - 1)
    ACTUATORS[random_actuator_index]()

if __name__ == "__main__":
    main_loop()

import time
import logging
from gpiozero import Motor, DigitalOutputDevice, GPIOError
from gpiozero.pins.pigpio import PiGPIOFailedUsageError

logging.basicConfig(level=logging.INFO)

class ChassisController:
    def __init__(self):
        self.left_motor = Motor(17, 18)
        self.right_motor = Motor(22, 23)
        self.ena_pin = DigitalOutputDevice(12)
        self.enb_pin = DigitalOutputDevice(13)
        self.ena_pin.on()
        self.enb_pin.on()

    def drive_forward(self, speed_fraction):
        self.left_motor.forward(speed_fraction)
        self.right_motor.forward(speed_fraction)

    def turn_left(self, speed_fraction):
        self.left_motor.backward(speed_fraction)
        self.right_motor.forward(speed_fraction)

    def turn_right(self, speed_fraction):
        self.left_motor.forward(speed_fraction)
        self.right_motor.backward(speed_fraction)

    def stop_all(self):
        self.left_motor.stop()
        self.right_motor.stop()

    def execute_command(self, command, duration):
        if command == "forward":
            self.drive_forward(0.5)
        elif command == "turn_left":
            self.turn_left(0.5)
        elif command == "turn_right":
            self.turn_right(0.5)
        elif command == "stop":
            self.stop_all()
        else:
            logging.error(f"Invalid command: {command}")

    def process_tilt(self, tilt_reading):
        tilt_commands = {
            ("forward", abs(tilt_reading) > 20),
            ("turn_left", tilt_reading < -20),
            ("stop", True),
        }

        for command, should_execute in tilt_commands:
            if should_execute:
                logging.info(f"Tilt: {tilt_reading}, Command: {command}")
                self.execute_command(command, 0.5)
                break

    def run(self, tilt_readings):
        for reading in tilt_readings:
            try:
                self.process_tilt(reading)
            except (GPIOError, PiGPIOFailedUsageError) as e:
                logging.error(f"Hardware error: {e}")
            except Exception as e:
                logging.error(f"Unexpected error: {e}")

if __name__ == "__main__":
    chassis_controller = ChassisController()

    def signal_handler(signal, frame):
        logging.info("Cleaning up and exiting...")
        chassis_controller.stop_all()
        exit(0)

    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    tilt_readings = [25, -25, 0, 30, -15, 40, -30, 10]
    chassis_controller.run(tilt_readings)

