import smbus2
import time
import threading
import signal
import math

class Magnetometer:
    def __init__(self, address=0x0D):
        self.address = address
        self.bus = smbus2.SMBus(1)
        self.shutdown_flag = False

    def initialize(self):
        for _ in range(3):
            try:
                self.bus.write_byte_data(self.address, 0x09, 0x40)  # Set control register
                self.bus.write_byte_data(self.address, 0x0A, 0x10)  # Set data rate register
                self.bus.write_byte_data(self.address, 0x0B, 0x01)  # Set mode register
                status = self.bus.read_byte_data(self.address, 0x06)
                if status != 0x00:  # Check if sensor is present
                    return True
            except Exception as e:
                print(f"Error during initialization: {e}")
            time.sleep(1)
        return False

    def read_data(self):
        while not self.shutdown_flag:
            try:
                x = (self.bus.read_byte_data(self.address, 0x00) << 8) | self.bus.read_byte_data(self.address, 0x01)
                y = (self.bus.read_byte_data(self.address, 0x02) << 8) | self.bus.read_byte_data(self.address, 0x03)
                z = (self.bus.read_byte_data(self.address, 0x04) << 8) | self.bus.read_byte_data(self.address, 0x05)
                x_offset = 20
                y_offset = -15
                heading = math.degrees(math.atan2(y - y_offset, x - x_offset))
                while heading < 0:
                    heading += 360
                print(f"Heading: {heading:.1f} degrees")
                time.sleep(0.1)
            except Exception as e:
                print(f"Error reading data: {e}")

def signal_handler(signal, frame):
    global shutdown_flag
    shutdown_flag = True

if __name__ == "__main__":
    magnetometer = Magnetometer()
    if not magnetometer.initialize():
        print("Failed to initialize magnetometer. Exiting.")
        exit(1)

    x_offset = 20
    y_offset = -15

    def acquisition_thread():
        magnetometer.read_data()

    acquisition_thread = threading.Thread(target=acquisition_thread)
    acquisition_thread.start()

    signal.signal(signal.SIGINT, signal_handler)

    try:
        while not shutdown_flag:
            time.sleep(1)
    except KeyboardInterrupt:
        pass

    magnetometer.bus.close()
    acquisition_thread.join()

