                self.pca.channels[channel].pwm_range = (self.MIN_PULSE_WIDTH, self.MAX_PULSE_WIDTH)

        except (ValueError, OSError) as e:
            logging.error(f"Error initializing PCA9685: {e}")
            sys.exit(1)

