import time
from gpiozero import DigitalInputDevice
import random

# Initialize the sensor connected to GPIO17 with pull-up enabled
try:
    sensor = DigitalInputDevice(17, pull_up=True)
except Exception as e:
    print(f"Error setting up GPIO: {e}")
    exit(1)

def get_vibration_amplitude():
    if sensor.value:  # HIGH (idle)
        return random.uniform(3.0, 5.0)
    else:  # LOW (vibration detected)
        return random.uniform(6.0, 9.0)

def main():
    amplitudes = []
    for _ in range(6):
        try:
            amplitude = get_vibration_amplitude()
            amplitudes.append(amplitude)
            time.sleep(0.3)  # Wait for 0.3 seconds
        except Exception as e:
            print(f"Error reading sensor: {e}")
            break

    if len(amplitudes) == 6:
        avg_amplitude = sum(amplitudes) / len(amplitudes)
        if avg_amplitude > 7.5:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

if __name__ == "__main__":
    main()

