def get_sensor_color_data():
    if sensor:
        try:
            color_data = sensor.color_rgb_bytes
            return color_data
        except Exception as e:
            print("Error reading sensor color data:", e)
            return (0, 0, 0, 0)
    return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        image = Image.open(image_path).resize((100, 100))
        colors = getcolors(image)
        dominant_color = max(colors, key=lambda p: p[0])
        return dominant_color[1]
    except FileNotFoundError:
        print("Image file not found.")
    except Exception as e:
        print("Error processing image:", e)
    return (0, 0, 0)

