import time
import wave
import numpy as np
from gpiozero import LED
import sounddevice as sd
from scipy.io.wavfile import read
import paho.mqtt.client as mqtt

# Initialize GPIO for LED
led = LED(18)

# MQTT broker details
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "voice_command"

# Command templates
COMMAND_TEMPLATES = {
    "on": np.array([...]),  # Replace with actual feature vector for "on" command
    "off": np.array([...]),  # Replace with actual feature vector for "off" command
    # Add more commands as needed
}

def extract_features(audio_data):
    energy = np.sum(np.square(audio_data))
    zcr = np.mean(np.diff(np.sign(audio_data)) - 0.5)
    return np.array([energy, zcr])

def recognize_command(features):
    distances = {command: np.linalg.norm(template - features) for command, template in COMMAND_TEMPLATES.items()}
    return min(distances, key=distances.get)

def audio_callback(indata, frames, time, status):
    if status:
        print("Error recording audio")
    else:
        audio_data = np.frombuffer(indata, dtype=np.int16)
        features = extract_features(audio_data)
        command = recognize_command(features)
        if command:
            print(f"Detected command: {command}, Distance: {distances[command]}")
            led.on()
            mqtt_publish(command)

def mqtt_publish(command):
    client = mqtt.Client()
    client.connect(MQTT_BROKER, MQTT_PORT)
    client.publish(MQTT_TOPIC, f"Command detected: {command}")
    client.disconnect()

try:
    with sd.InputStream(callback=audio_callback, samplerate=16000, channels=1, blocksize=100):
        while True:
            time.sleep(0.1)

except KeyboardInterrupt:
    print("Exiting...")

except Exception as e:
    print(f"An error occurred: {e}")

finally:
    led.off()
    sd.stop()

