from adafruit_motor.motor import MotorError
from adafruit_motor.motorhat import MotorHAT

logging.basicConfig(level=logging.INFO)

class DCMotorHATExtra(MotorHAT):
    def __init__(self, i2c_bus=1, i2c_address=0x60, pwm_freq=60):
        super().__init__(i2c_bus, address=i2c_address)
        self.pwm_freq = pwm_freq
        self.motors = []
        self.atexit_handler = self.release_all_motors
        self.signal_handler = self.clean_shutdown
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def set_pwm_freq(self, freq):
        if freq > 0:
            self.pwm_freq = freq
            self.setSpeed(self.pwm_freq)
        else:
            raise ValueError("PWM frequency must be greater than zero.")

    def get_pwm_freq(self):
        return self.pwm_freq

    def release_all_motors(self):
        for motor in self.motors:
            motor.release()

    def clean_shutdown(self, signum, frame):
        self.release_all_motors()
        sys.exit(0)

    def add_motor(self, motor_num, invert=False):
        if 1 <= motor_num <= 4:
            self.motors.append(DCMotor(self, motor_num, self.pwm_freq, invert))
        else:
            raise ValueError("Motor number must be between 1 and 4.")

    def get_motor(self, motor_num):
        for motor in self.motors:
            if motor.number == motor_num:
                return motor
        raise ValueError(f"No motor found with number {motor_num}.")


class DCMotor:
    def __init__(self, hat, motor_num, pwm_freq, invert=False):
        if not isinstance(hat, DCMotorHATExtra):
            raise TypeError("The 'hat' argument must be an instance of DCMotorHATExtra.")
        if motor_num < 1 or motor_num > 4:
            raise ValueError("Motor number must be between 1 and 4.")
        self.hat = hat
        self.number = motor_num
        self.pwm_freq = pwm_freq
        self.invert = invert
        self.last_duty_cycle = 0
        self.motor = hat.get_motor(motor_num)

    def set_dc(self, duty_cycle):
        if not -255 <= duty_cycle <= 255:
            duty_cycle = max(-255, min(255, duty_cycle))
            logging.warning(f"Duty cycle {duty_cycle} is out of range [-255, 255]. Clamping to {duty_cycle}.")
        if duty_cycle == 0:
            self.stop()
            return
        direction = MotorError.FORWARD if (duty_cycle ^ self.invert) < 0 else MotorError.BACKWARD
        self.motor.setSpeed(abs(duty_cycle))
        self.motor.direction = direction
        self.last_duty_cycle = duty_cycle

    def stop(self):
        self.set_dc(0)

    def close(self):
        self.hat.motors.remove(self)

    def get_status(self):
        return {
            "number": self.number,
            "pwm_freq": self.pwm_freq,
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }


# Example usage
if __name__ == "__main__":
    try:
        hat = DCMotorHATExtra()
        hat.set_pwm_freq(hat.get_pwm_freq())

        motor1 = hat.add_motor(1, invert=True)

        for dc in range(-255, 256, 25):
            motor1.set_dc(dc)
            time.sleep(0.1)

        motor1.stop()

        # Clean up resources on exit
        hat.atexit_handler()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        hat.release_all_motors()
        sys.exit(1)
