import pigpio

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi: pigpio.pi, pin: int):
        if not isinstance(pi, pigpio.pi) or not pi.connected:
            raise MotorError("Invalid pigpio instance")
        if pin < 0 or pin > 23:
            raise MotorError("Invalid GPIO pin")

        self.pi = pi
        self.pin = pin
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(self.pin, 1000)
        self.pi.set_PWM_dutycycle(self.pin, 0)

    def set_frequency(self, freq: int):
        if not 1 <= freq <= 10000:
            raise MotorError("Frequency must be between 1 and 10000 Hz")
        rc = self.pi.set_PWM_frequency(self.pin, freq)
        if rc != 0:
            raise MotorError("Failed to set PWM frequency") from None

    def set_duty_cycle(self, duty: int):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be an integer between 0 and 255")
        self.pi.set_PWM_dutycycle(self.pin, duty)
        if self.pi.fault:
            raise MotorError("Failed to set PWM duty cycle") from None

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.pi.stop()

    def __del__(self):
        self.close()

