import logging
import time
import RPi.GPIO as GPIO
from gpiozero import Servo

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ServoController:
    def __init__(self, servo_pin=18):
        if not GPIO.RPI_GPIO_AVAILABLE:
            logging.error("RPi.GPIO library is not available.")
            return
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(servo_pin, GPIO.OUT)
            self.servo = Servo(GPIO.get_pin(servo_pin))
        except Exception as e:
            logging.error(f"Failed to initialize servo: {e}")
            GPIO.cleanup()
            return

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.servo.value = duty_cycle
        logging.info(f"Moved servo to {angle} degrees.")

    def _angle_to_duty_cycle(self, angle):
        return angle / 18 * 2.5  # 2.5% duty cycle for 0 degrees, 12.5% for 180 degrees

    def stop(self):
        self.servo.value = 0
        logging.info("Servo stopped.")

    @staticmethod
    def main(angles):
        controller = ServoController()
        if controller is None:
            return

        for angle in angles:
            controller.move_to(angle)
            time.sleep(0.5)

        controller.stop()
        GPIO.cleanup()

if __name__ == "__main__":
    try:
        ServoController.main([0, 45, 90, 135, 180, 135, 90, 45, 0])
    except KeyboardInterrupt:
        logging.info("Program stopped by user.")
        ServoController.main([]).stop()
        GPIO.cleanup()

