import time
import logging
import signal
import sys

logging.basicConfig(level=logging.WARNING)

class ServoController:
    REGISTER_MAP = {
        "STATUS": {"R/W": "R", "Register": 0x3000, "functioncode": pymodbus.constants.FC_READ_HOLDING_REGISTERS},
        "CONTROL": {"R/W": "W", "Register": 0x3100, "functioncode": pymodbus.constants.FC_WRITE_SINGLE_REG},
        "OPMODE": {"R/W": "W", "Register": 0x3500, "functioncode": pymodbus.constants.FC_WRITE_SINGLE_REG},
        "PositionFeedback": {"R/W": "R", "Register": 0x3700, "functioncode": pymodbus.constants.FC_READ_HOLDING_REGISTERS, "read_length": 2},
        "VelocityFeedback": {"R/W": "R", "Register": 0x3B00, "functioncode": pymodbus.constants.FC_READ_HOLDING_REGISTERS, "read_length": 2},
        "PositionCommand": {"R/W": "W", "Register": 0x4000, "functioncode": pymodbus.constants.FC_WRITE_SINGLE_REG},
        "VelocityCommand": {"R/W": "W", "Register": 0x6F00, "functioncode": pymodbus.constants.FC_WRITE_MULTIPLE_REG},
    }

    def __init__(self):
        self.serial = None
        self.rtu = pymodbus.RTUSerial(port='/dev/serial0', baudrate=115200, timeout=1)
        self.rtu.serial.port.timeout = 1
        self.rtu.serial.port.xonxoff = False
        self.rtu.serial.port.rtscts = False
        self.rtu.serial.port.dsrd = False
        self.rtu.serial.port.cd = False
        self.rtu.serial.port.cts = False
        self.rtu.serial.port.dtr = False

    def __enter__(self):
        self.serial = serial.Serial('/dev/serial0', 115200, timeout=1)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial:
            self.serial.close()
            self.serial = None

    def write_register(self, reg_addr, value):
        if self.serial:
            try:
                self.rtu.write_register(reg_addr, value)
                if self.REGISTER_MAP[reg_addr]['functioncode'] == pymodbus.constants.FC_WRITE_SINGLE_REG:
                    logging.info(f"Wrote {value} to register {reg_addr:04X}")
            except pymodbus.DataWhiffError as e:
                logging.error(f"CRC error writing to register {reg_addr:04X}: {e}")
            except pymodbus.ResponseParsingError as e:
                logging.error(f"Failed to parse response from register {reg_addr:04X}: {e}")
            except Exception as e:
                logging.error(f"Unexpected error writing to register {reg_addr:04X}: {e}")

    def read_register(self, reg_addr):
        if self.serial:
            try:
                response = self.rtu.read_holding_registers(reg_addr, 1)
                if response and len(response) == 1:
                    return response[0].value
                else:
                    logging.warning(f"Unexpected response length from register {reg_addr:04X}")
                    return None
            except pymodbus.DataWhiffError as e:
                logging.error(f"CRC error reading from register {reg_addr:04X}: {e}")
            except pymodbus.ResponseParsingError as e:
                logging.error(f"Failed to parse response from register {reg_addr:04X}: {e}")
            except Exception as e:
                logging.error(f"Unexpected error reading from register {reg_addr:04X}: {e}")

    def set_control(self, start_stop):
        if self.serial:
            try:
                self.write_register(self.REGISTER_MAP["CONTROL"]["Register"], start_stop)
            except Exception as e:
                logging.error(f"Failed to set control register: {e}")

    def get_status(self):
        if self.serial:
            try:
                return self.read_register(self.REGISTER_MAP["STATUS"]["Register"])
            except Exception as e:
                logging.error(f"Failed to get status register: {e}")
                return None

    def set_opmode(self, mode):
        if self.serial:
            try:
                self.write_register(self.REGISTER_MAP["OPMODE"]["Register"], self.REGISTER_MAP["OPMODE"]["Value"]["Value"])
            except Exception as e:
                logging.error(f"Failed to set opmode: {e}")

    def get_position_feedback(self):
        if self.serial:
            try:
                return self.read_register(self.REGISTER_MAP["PositionFeedback"]["Register"])
            except Exception as e:
                logging.error(f"Failed to get position feedback: {e}")
                return None

    def get_velocity_feedback(self):
        if self.serial:
            try:
                return self.read_register(self.REGISTER_MAP["VelocityFeedback"]["Register"])
            except Exception as e:
                logging.error(f"Failed to get velocity feedback: {e}")
                return None

    def set_position_command(self, position):
        if self.serial:
            try:
                self.write_register(self.REGISTER_MAP["PositionCommand"]["Register"], position)
            except Exception as e:
                logging.error(f"Failed to set position command: {e}")

    def set_velocity_command(self, velocity):
        if self.serial:
            try:
                self.write_register(self.REGISTER_MAP["VelocityCommand"]["Register"], velocity)
            except Exception as e:
                logging.error(f"Failed to set velocity command: {e}")

# Example usage
with ServoController() as servo:
    servo.set_control(0x000F)  # Start the motor
    time.sleep(2)
    print(f"Status: {bin(servo.get_status())}")
    servo.set_opmode(1)  # Set to position mode
    position = servo.get_position_feedback()
    print(f"Current Position: {position}")
    servo.set_position_command(180)  # Move to position 180
    velocity = servo.get_velocity_feedback()
    print(f"Current Velocity: {velocity}")
    servo.set_velocity_command(100)  # Set velocity to 100

