        try:
            self.serial_port = serial.Serial('/dev/serial0', 115200, timeout=1)
            self.modbus_instrument = TwoWireModbusInstrument(self.serial_port)
            self.modbus_instrument.serial.baudrate = 115200
            self.modbus_instrument.serial.bytesize = serial.EIGHTBITS
            self.modbus_instrument.serial.parity = serial.PARITY_NONE
            self.modbus_instrument.serial.stopbits = serial.STOPBITS_ONE
        except serial.SerialException:
            logging.error("Serial port /dev/serial0 not available. Exiting.")
            sys.exit(0)

    def set_operation_mode(self, mode):
        if not isinstance(mode, int) or mode not in [0, 1]:
            raise ValueError("Mode must be 0 or 1")
        try:
            self.modbus_instrument.write_register(0x3500, mode)
        except ModbusTimeoutException:
            logging.error("Modbus write timeout")
            return False
        return True

    def write_position_command(self, value):
        if not isinstance(value, (int, float)) or not (0 <= value <= 180):
            raise ValueError("Value must be an integer between 0 and 180")
        try:
            self.modbus_instrument.write_register(0x4000, int(value))
        except ModbusTimeoutException:
            logging.error("Modbus write timeout")
            return False
        return True

    def write_velocity_command(self, value):
        if not isinstance(value, (int, float)) or not (0 <= value <= 100):
            raise ValueError("Value must be a float between 0 and 100")
        try:
            self.modbus_instrument.write_register(0x6F00, int(value * 100))
        except ModbusTimeoutException:
            logging.error("Modbus write timeout")
            return False
        return True

    def read_position_feedback(self):
        try:
            position = self.modbus_instrument.read_holding_registers(0x3700, 2)
            return position[0] / 100.0, position[1] / 100.0
        except ModbusTimeoutException:
            logging.error("Modbus read timeout")
            return None, None

    def read_velocity_feedback(self):
        try:
            velocity = self.modbus_instrument.read_holding_registers(0x3B00, 2)
            return velocity[0] / 100.0, velocity[1] / 100.0
        except ModbusTimeoutException:
            logging.error("Modbus read timeout")
            return None, None

    def start(self):
        try:
            self.modbus_instrument.write_register(0x3100, 0x000F)
        except ModbusTimeoutException:
            logging.error("Modbus write timeout")
            return False

    def stop(self):
        try:
            self.modbus_instrument.write_register(0x3100, 0x0006)
        except ModbusTimeoutException:
            logging.error("Modbus write timeout")
            return False

    def read_status(self):
        try:
            status = self.modbus_instrument.read_holding_registers(0x3000, 1)[0]
            return status
        except ModbusTimeoutException:
            logging.error("Modbus read timeout")
            return None

