import serial
import time
import threading
import RPi.GPIO as GPIO
import logging

logging.basicConfig(filename='seed_sorter.log', level=logging.INFO)

SCALE_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
BUTTON_PIN = 2
SOLENOID_PIN = 17
WEIGHT_THRESHOLD = 0.25
SOLENOID_DURATION = 0.5
MAX_SOLENOID_DURATION = 1

ser = None
button_thread = None
solenoid_thread = None

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(SOLENOID_PIN, GPIO.OUT)

def serial_data_acquisition():
    global ser
    try:
        ser = serial.Serial(SCALE_PORT, BAUD_RATE)
        while True:
            if GPIO.input(BUTTON_PIN):
                weight_str = ser.readline().decode().strip()
                if weight_str.isdigit():
                    weight = float(weight_str)
                    solenoid_thread.set_value(weight)
                else:
                    logging.error(f"Invalid weight data: {weight_str}")
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")

def solenoid_control():
    global solenoid_thread
    GPIO.output(SOLENOID_PIN, GPIO.HIGH)
    time.sleep(SOLENOID_DURATION)
    GPIO.output(SOLENOID_PIN, GPIO.LOW)
    solenoid_thread.set_value(False)

def solenoid_duration_monitor():
    start_time = time.time()
    while True:
        if solenoid_thread.value:
            elapsed_time = time.time() - start_time
            if elapsed_time > MAX_SOLENOID_DURATION:
                logging.error("Solenoid duration limit exceeded")
                GPIO.output(SOLENOID_PIN, GPIO.LOW)
                start_time = time.time()
        time.sleep(0.1)

def main():
    setup_gpio()
    button_thread = threading.Thread(target=button_monitoring)
    button_thread.start()

    solenoid_thread = threading.Thread(target=solenoid_control_loop)
    solenoid_thread.start()

    solenoid_duration_thread = threading.Thread(target=solenoid_duration_monitor)
    solenoid_duration_thread.start()

    try:
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        GPIO.cleanup()
        if ser:
            ser.close()

def button_monitoring():
    global button_thread
    while True:
        if GPIO.input(BUTTON_PIN):
            logging.info("Button pressed")
            button_thread = threading.Thread(target=serial_data_acquisition)
            button_thread.start()

def solenoid_control_loop():
    global solenoid_thread
    while True:
        if solenoid_thread.value:
            logging.info("Solenoid activated")
            solenoid_control()
        else:
            logging.info("Solenoid deactivated")

if __name__ == "__main__":
    main()

