import time
import board
import adafruit_pca9685
from adafruit_servokit import ServoKit

# Define servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Define drop angles
METAL = 135
PLASTIC = 180
PAPER = 90

# Initialize ServoKit
try:
    i2c_bus = board.I2C()
    servokit = ServoKit(channels=16, i2c_address=0x40, i2c_bus=i2c_bus)
except (ValueError, IOError) as e:
    print(f"Error initializing ServoKit: {e}")
    exit(1)

def move_servo(channel, target_angle, step_size=5, delay=0.04):
    if not (0 <= channel < 16):
        raise ValueError("Channel must be between 0 and 15")
    if not (0 <= target_angle <= 180):
        raise ValueError("Angle must be between 0 and 180")

    for current_angle in range(target_angle, 0, -step_size):
        servokit.servo[channel].angle = current_angle
        time.sleep(delay)

    for current_angle in range(target_angle, 180, -step_size):
        servokit.servo[channel].angle = current_angle
        time.sleep(delay)

def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, 90)

def drop(angle):
    move_servo(DROP, angle)

def pick(angle):
    move_servo(GRAB, angle)

def grab(angle):
    move_servo(GRAB, 120)

def release(angle):
    move_servo(DROP, 100)

def collect_object_steps(seek_angle):
    seek(seek_angle)
    grab(90)
    drop(160)
    pick(100)
    grab(90)

def drop_object_steps(drop_angle):
    move_servo(DROP, drop_angle, step_size=2, delay=0.01)
    grab(120)
    move_servo(DROP, 100)

def get_pos_x(x_center):
    return max(0, min(180, (x_center / 320) * 180))

def get_pos_y(y_center):
    return max(0, min(180, (y_center / 320) * 180))

def collect_object(x_center, y_center, drop_angle):
    seek_angle = get_pos_x(x_center)
    drop_angle = get_pos_y(y_center)

    try:
        base_angle = get_pos_y(160)  # Adjust base angle as needed
        move_servo(BASE, base_angle)

        collect_object_steps(seek_angle)
        collect_object(x_center, y_center, drop_angle)
        drop_object_steps(drop_angle)

        deseek(90)
        grab(90)
        release(100)

    except KeyboardInterrupt:
        print("Collect_object interrupted, stopping servos and releasing I2C bus.")
        servokit.servo.off()
        servokit.i2c.close()

try:
    collect_object(160, 120, 135)
except KeyboardInterrupt:
    print("Exiting gracefully...")
    servokit.servo.off()
    servokit.i2c.close()

