import serial
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')

class RelayController:
    def __init__(self, port='/dev/ttyUSB0', baudrate=9600, command='RELAY1 ON\n'):
        self.ser = None
        self.port = port
        self.baudrate = baudrate
        self.command = command
        self.running = True

    def setup_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            if not self.ser.is_open:
                raise serial.SerialException("Failed to open serial port")
            self.ser.flushInput()
        except (serial.SerialException, OSError) as e:
            logging.error(f"Error opening serial port: {e}")
            sys.exit(1)

    def send_command(self):
        try:
            self.ser.write(self.command.encode())
            if self.ser.in_waiting > 0:
                logging.warning("Stale data in input buffer, flushing...")
                self.ser.readline()
            if self.ser.inWaiting() != len(self.command):
                logging.warning("Short write, expected %d bytes, got %d", len(self.command), self.ser.inWaiting())
        except serial.SerialException as e:
            logging.error(f"Error sending command: {e}")

    def run(self):
        self.setup_serial()
        try:
            while self.running:
                self.send_command()
                time.sleep(5)
        except KeyboardInterrupt:
            logging.info("Exiting on user request")
        finally:
            self.ser.close()
            logging.info("Serial port closed")

def signal_handler(signal, frame):
    logging.info("Received signal, exiting...")
    relay_controller.running = False

if __name__ == "__main__":
    relay_controller = RelayController()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    relay_controller.run()

