    phrase = phrase.lower()
    if "pump" in phrase and "on" in phrase:
        return "pump_on"
    elif "pump" in phrase and "off" in phrase:
        return "pump_off"
    elif "light" in phrase and "toggle" in phrase:
        return "light_toggle"
    else:
        print(f"Warning: Unknown intent in phrase: {phrase}")
        return None

