        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command"
    ]

    for phrase in test_phrases:
        intent = parse_intent(phrase)
        if intent:
            print(f"Parsed intent: {intent} for phrase: {phrase}")
            if intent == "pump_on":
                pump.on()
            elif intent == "pump_off":
                pump.off()
            elif intent == "light_toggle":
                light.toggle()
            time.sleep(1)  # Delay to see the effect

    # Safe shutdown on KeyboardInterrupt or exception
    try:
        while True:
            time.sleep(1)
    except (KeyboardInterrupt, Exception) as e:
        print(f"Exiting due to {e}. Shutting down actuators.")
        pump.close()
        light.close()

if __name__ == "__main__":
    main()

