import smbus2
import time
from datetime import datetime

class DS1338RTC:
    def __init__(self, bus_num=1, addr=0x68):
        self.bus = smbus2.SMBus(bus_num)
        self.addr = addr
        if not self.present():
            raise IOError("DS1338 RTC not found on I2C bus")

    def present(self):
        try:
            self.bus.read_byte_data(self.addr, 0x00)
            return True
        except (IOError, ValueError):
            return False

    def _to_bcd(self, val):
        return ((val >> 4) & 0x0F) | (((val & 0x0F) << 4) + ((val >> 4) & 0x0F) * 0x10)

    def _from_bcd(self, bcd):
        return ((bcd >> 4) & 0x0F) + ((bcd & 0x0F) * 0x10)

    def read_seconds(self):
        return self._from_bcd(self.bus.read_byte_data(self.addr, 0x00))

    def write_seconds(self, val):
        self.bus.write_byte_data(self.addr, 0x00, self._to_bcd(val))

    # Similar methods for minutes, hours, date, month, and year...

    def read_datetime(self, century=21):
        secs = self.read_seconds()
        mins = self.read_minutes()
        hours = self.read_hours() & 0x3F
        date = self.read_date()
        month = self.read_month()
        year = self.read_year() + (century * 100)
        return datetime(2100 + (year // 100), 1, 1, hours, mins, secs)

    def write_all(self, sec=None, min=None, hr=None, day=None, mon=None, year=None):
        if sec is not None:
            self.write_seconds(sec)
        if min is not None:
            self.write_minutes(min)
        if hr is not None:
            self.write_hours(hr)
        if day is not None:
            self.write_date(day)
        if mon is not None:
            self.write_month(mon)
        if year is not None:
            self.write_year(year)

    def __del__(self):
        self.bus.close()

