        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.lcd = LCD1602(rs=GPIOIn(17), en=GPIOIn(27), d4=GPIOIn(22), d5=GPIOIn(18), d6=GPIOIn(23), d7=GPIOIn(25), cols=16, lines=2)
