        try:
            response = self.ser.read_until(wait_for, timeout)
            if response:
                return response
            else:
                return None
        except serial.SerialTimeoutException:
            return None

    def test_connection(self):
        response = self._send_command(b'AT')
        if response == b'AT':
            self.lcd.message = "Connection OK"
            self.lcd.update()
        else:
            self.lcd.message = "Connection Failed"
            self.lcd.update()

    def restart(self):
        self._send_command(b'AT+RST')
        time.sleep(2)
        self.test_connection()

