        self._send_command(b'AT+CIFSR')
        ip_response = self.ser.read_until(b'\r\n', self.timeout)
        if ip_response and b'IP:' in ip_response:
            ip_index = ip_response.index(b'IP:')
            return ip_response[ip_index + 2:].split(b',')[0]
        return None

