            self._send_command(b'AT+CIPSEND=%d,%d' % (len(data), 1), timeout=10)
            self.ser.write(data)
        self._send_command(b'AT+CIPCLOSE')
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        response = b''
        while True:
            try:
                data = self.ser.read_until(b'\r\n', timeout)
                if b'CLOSED' in data:
                    break
                response += data
                if b'HTTP/1.1' in data:
                    break
            except serial.SerialTimeoutException:
                break
        return response

    def __del__(self):
        self.ser.close()

