            logging.error(f"Error opening serial port: {e}")
            sys.exit(1)

    def teardown(self):
        if self.ser:
            self.ser.close()

    def read_data(self):
        if self.ser is None:
            logging.error("Serial port not initialized, cannot read data.")
            return

        try:
            line = self.ser.readline().decode().strip()
            if not line:
                logging.warning("No data received from the sensor.")
                return

            try:
                hr, spo2 = map(float, line.split(','))
                self.log_reading(hr, spo2)
                self.print_reading(hr, spo2)
            except ValueError as e:
                logging.error(f"Error parsing data: {e}. Raw data: {line}")
        except serial.SerialTimeoutException:
            logging.warning("Timeout while reading from the sensor.")
        except Exception as e:
            logging.error(f"Unexpected error: {e}")


    def log_reading(self, hr, spo2):
        with open('health_readings_log.txt', 'a') as log_file:
            log_file.write(f"Heart Rate: {hr:.0f} bpm, SpO2: {spo2:.2f} %\n")

    def print_reading(self, hr, spo2):
        print(f"Heart Rate: {hr:.0f} bpm, SpO2: {spo2:.2f} %")

    def run(self):
        self.setup()
        try:
            while True:
                self.read_data()
                time.sleep(5)
        except KeyboardInterrupt:
            self.teardown()
            logging.info("Program terminated by user.")
        except Exception as e:
            self.teardown()
            logging.error(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    reader = PulseOximeterReader()
    reader.run()
