class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.gps = gps()

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            return True
        except (serial.SerialException, OSError) as e:
            log.error(f"Error connecting to GPS: {e}")
            return False

    def read_data(self):
        if self.ser is None or not self.ser.is_open:
            return None
        try:
            data = self.ser.readline().decode('utf-8').strip()
            return data
        except (serial.SerialTimeoutException, serial.SerialException):
            log.error("Error reading from GPS")
            self.close()
            return None

    def parse_gga(self, sentence):
        try:
            if sentence.startswith('$GPGGA') or sentence.startswith('$GNGGA'):
                parts = sentence.split(',')
                utc_time = parts[1] + parts[2]
                latitude = parts[3] + parts[4][:-1] if parts[4][-1] in ['N', 'S'] else None
                longitude = parts[5] + parts[6][:-1] if parts[6][-1] in ['E', 'W'] else None
                fix_quality = parts[7]
                num_satellites = int(parts[9])
                return {
                    'utc_time': utc_time,
                    'latitude': latitude,
                    'longitude': longitude,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
            else:
                log.warning("Invalid NMEA sentence for GGA parsing")
                return None
        except (IndexError, ValueError) as e:
            log.error(f"Error parsing GGA sentence: {e}")
            return None

    def close(self):
        if self.ser is not None and self.ser.is_open:
            try:
                self.ser.close()
            except Exception as e:
                log.error(f"Error closing serial port: {e}")
            self.ser = None

def main():
    gps_device = SimpleGPS()
    if gps_device.connect():
        log.info("Connected to GPS device")
        while True:
            data = gps_device.read_data()
            if data:
                parsed_data = gps_device.parse_gga(data)
                if parsed_data:
                    log.info(f"Parsed GPS data: {parsed_data}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        gps_device.close()
        log.info("Cleanly exiting")

if __name__ == "__main__":
