import os
import threading
import serial
import time
from flask import Flask, request, jsonify, abort
from contextlib import contextmanager

app = Flask(__name__)
serial_lock = threading.Lock()

class SerialCommunicator:
    def __init__(self, port, baudrate):
        self.ser = None
        self.port = port
        self.baudrate = baudrate

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def open(self):
        with serial_lock:
            try:
                self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            except serial.SerialException as e:
                raise Exception(f"Failed to open serial port: {e}")

    def send(self, cmd):
        with serial_lock:
            if self.ser is None:
                raise Exception("Serial port not open")
            self.ser.write((cmd + "\n").encode())
            self.ser.flush()

    def receive_line(self):
        with serial_lock:
            if self.ser is None:
                return None
            try:
                return self.ser.readline().decode().strip()
            except serial.SerialTimeoutException:
                return None
            except Exception as e:
                raise Exception(f"Error reading from serial port: {e}")

    def close(self):
        with serial_lock:
            if self.ser is not None:
                self.ser.close()
                self.ser = None

@app.route('/version', methods=['GET'])
def get_version():
    try:
        with SerialCommunicator('/dev/ttyUSB0', 9600) as sc:
            sc.send('*IDN?\n')
            response = sc.receive_line()
            if response is None:
                return jsonify({'error': 'No response from instrument'}), 504
            return jsonify({'version': response}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

class DataManager:
    def __init__(self):
        self.data = [
            {'id': 1, 'name': 'Item 1', 'done': False},
            {'id': 2, 'name': 'Item 2', 'done': False}
        ]
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data

    def get_by_id(self, id):
        with self.lock:
            for item in self.data:
                if item['id'] == id:
                    return item
            return abort(404)

    def create(self, name, done):
        if not name or not isinstance(done, bool):
            abort(400)
        with self.lock:
            new_id = len(self.data) + 1
            self.data.append({'id': new_id, 'name': name, 'done': done})
            return jsonify({'id': new_id, 'name': name, 'done': done}), 201

data_manager = DataManager()

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify(data_manager.get_all())

@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    item = data_manager.get_by_id(item_id)
    if isinstance(item, int):
        return jsonify(item.__dict__)
    return abort(404)

@app.route('/data', methods=['POST'])
def create_item():
    try:
        name = request.json.get('name')
        done = request.json.get('done')
        return data_manager.create(name, done)
    except Exception as e:
        return abort(400)

def signal_handler(sig, frame):
    if hasattr(app, 'serial_communicator'):
        app.serial_communicator.close()
    os._exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)

