LOG_FILE = 'access_log.txt'
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def log_access(tag_id):
    try:
        with open(LOG_FILE, 'a') as log:
            log.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - RFID Tag: {tag_id}\n")
        print(f"Access granted for RFID Tag: {tag_id}")
    except IOError as e:
        print(f"Error writing to log file: {e}")

try:
    ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    ser.flush()

    while True:
        try:
            if not ser.in_waiting:
                print("No new data from RFID reader.")
                continue

            line = ser.readline().decode('ascii').strip()
            if line:
                log_access(line)

        except serial.SerialException as e:
            print(f"Error reading from RFID reader: {e}")
            break
        except KeyboardInterrupt:
            print("\nProgram interrupted by user. Exiting...")
            break

    finally:
        ser.close()

except Exception as e:
    print(f"An unexpected error occurred: {e}")
    if 'ser' in locals() and ser.is_open:
        ser.close()

